import {clamp} from './simulation.js?v=11';
export function createControls(state,actions){
 const wheel=document.querySelector('#wheel'),art=document.querySelector('#wheel-art');const keys=new Set();let stickPointer=null,stickX=0,stickY=0;let wheelPointer=null,lastAngle=0,lookPointer=null,lastX=0,lastY=0;let walkPointer=null,walkX=0,walkY=0,runHeld=false;const heldPedals=new Map(),heldLift=new Map();const input={moveX:0,moveY:0,run:false,aileron:0,elevator:0,rudder:0,lift:0,look:0,pitch:0,lookTarget:0,pitchTarget:0};
 const angle=e=>{const r=wheel.getBoundingClientRect();return Math.atan2(e.clientY-r.top-r.height/2,e.clientX-r.left-r.width/2)*180/Math.PI;};
 wheel.addEventListener('pointerdown',e=>{if(!actions.active())return;e.preventDefault();wheelPointer=e.pointerId;lastAngle=angle(e);wheel.setPointerCapture(e.pointerId);});
 wheel.addEventListener('pointermove',e=>{if(e.pointerId!==wheelPointer)return;const next=angle(e);let delta=next-lastAngle;if(delta>180)delta-=360;if(delta< -180)delta+=360;state.steering=clamp(state.steering+delta,-540,540);lastAngle=next;});
 const releaseWheel=e=>{if(e.pointerId===wheelPointer)wheelPointer=null;};wheel.addEventListener('pointerup',releaseWheel);wheel.addEventListener('pointercancel',releaseWheel);wheel.addEventListener('lostpointercapture',releaseWheel);
 for(const [id,property] of [['brake','brake'],['accelerator','throttle']]){const el=document.getElementById(id);const set=e=>{const rect=el.getBoundingClientRect();state[property]=clamp((rect.bottom-e.clientY-8)/(rect.height-20),0,1);if(state.flight&&property==='throttle')state.flightThrottle=state.throttle;};el.addEventListener('pointerdown',e=>{if(!actions.active())return;e.preventDefault();heldPedals.set(property,e.pointerId);el.setPointerCapture(e.pointerId);set(e)});el.addEventListener('pointermove',e=>{if(heldPedals.get(property)===e.pointerId)set(e)});const up=e=>{if(heldPedals.get(property)===e.pointerId){heldPedals.delete(property);if(!(state.flight&&property==='throttle'))state[property]=0;}};el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',up);el.addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();e.stopPropagation();if(!actions.active())return;state[property]=clamp(state[property]+(e.key==='ArrowUp'?.1:-.1),0,1);if(state.flight&&property==='throttle')state.flightThrottle=state.throttle;heldPedals.set(property,'keyboard');}if(e.key==='Escape'){heldPedals.delete(property);state[property]=0;}});el.addEventListener('blur',()=>{if(heldPedals.get(property)==='keyboard'){heldPedals.delete(property);if(!(state.flight&&property==='throttle'))state[property]=0;}});}
 wheel.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home'].includes(e.key)){e.preventDefault();e.stopPropagation();if(!actions.active())return;state.steering=e.key==='Home'?0:clamp(state.steering+(e.key==='ArrowRight'?45:-45),-540,540);}});
 // Keep a keyboard-held brake depressed while selecting a gear or releasing P.
 for(const button of document.querySelectorAll('[data-gear],#parking-brake'))button.addEventListener('pointerdown',e=>{if(heldPedals.get('brake')==='keyboard')e.preventDefault();});
 const stick=document.getElementById('flight-stick');
 const moveStick=e=>{const r=stick.getBoundingClientRect(),range=r.width*.36;stickX=clamp((e.clientX-r.left-r.width/2)/range,-1,1);stickY=clamp((e.clientY-r.top-r.height/2)/range,-1,1);};
 stick?.addEventListener('pointerdown',e=>{if(!actions.active()||!state.flight)return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e);});
 stick?.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e);});
 for(const type of ['pointerup','pointercancel','lostpointercapture'])stick?.addEventListener(type,e=>{if(e.pointerId===stickPointer){stickPointer=null;stickX=stickY=0;}});
 const zone=document.querySelector('#look-zone');zone.addEventListener('pointerdown',e=>{lookPointer=e.pointerId;lastX=e.clientX;lastY=e.clientY;zone.setPointerCapture(e.pointerId)});zone.addEventListener('pointermove',e=>{if(e.pointerId!==lookPointer)return;if(state.onFoot){state.yaw+=(e.clientX-lastX)*.006;input.lookTarget=input.look=0;}else input.lookTarget=clamp(input.lookTarget+(e.clientX-lastX)*.006,-1.48,1.48);input.pitchTarget=clamp(input.pitchTarget+(e.clientY-lastY)*.002,state.onFoot?-.6:-.2,state.onFoot?.6:.26);lastX=e.clientX;lastY=e.clientY;});zone.addEventListener('pointerup',()=>lookPointer=null);zone.addEventListener('pointercancel',()=>lookPointer=null);
 for(const [id,direction]of [['flight-up',1],['flight-down',-1]]){const el=document.getElementById(id);if(!el)continue;el.addEventListener('pointerdown',e=>{if(!actions.active())return;e.preventDefault();el.setPointerCapture(e.pointerId);heldLift.set(e.pointerId,direction);});for(const name of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(name,e=>heldLift.delete(e.pointerId));}
 const walk=document.getElementById('walk-stick'),run=document.getElementById('walk-run');
 const moveWalk=e=>{const r=walk.getBoundingClientRect(),range=r.width*.36;walkX=clamp((e.clientX-r.left-r.width/2)/range,-1,1);walkY=clamp(-(e.clientY-r.top-r.height/2)/range,-1,1);};
 walk?.addEventListener('pointerdown',e=>{if(!actions.active()||!state.onFoot)return;e.preventDefault();walkPointer=e.pointerId;walk.setPointerCapture(e.pointerId);moveWalk(e);});walk?.addEventListener('pointermove',e=>{if(e.pointerId===walkPointer)moveWalk(e);});for(const type of ['pointerup','pointercancel','lostpointercapture'])walk?.addEventListener(type,e=>{if(e.pointerId===walkPointer){walkPointer=null;walkX=walkY=0;}});
 run?.addEventListener('pointerdown',e=>{if(!actions.active())return;e.preventDefault();runHeld=true;run.setPointerCapture(e.pointerId);});for(const type of ['pointerup','pointercancel','lostpointercapture'])run?.addEventListener(type,()=>runHeld=false);
 const drivingKeys=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyQ','KeyE','KeyC','KeyF','KeyM','KeyZ','KeyX','KeyV','ShiftLeft','ShiftRight'];
 document.addEventListener('keydown',e=>{if(e.code==='Escape'){actions.pause();return;}if(!actions.active()||e.target.closest('dialog,select'))return;if(drivingKeys.includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Space'&&!state.flight&&!state.onFoot)actions.parking();if(e.code==='KeyQ'&&!state.flight&&!state.onFoot)actions.signal(-1);if(e.code==='KeyE'&&!state.flight&&!state.onFoot)actions.signal(1);if(e.code==='KeyC')actions.camera();if(e.code==='KeyF')actions.flight?.();if(e.code==='KeyM')actions.fire?.();if(e.code==='KeyV')actions.exit?.();});document.addEventListener('keyup',e=>keys.delete(e.code));
 function release(){walkPointer=null;walkX=walkY=0;runHeld=false;input.moveX=input.moveY=0;input.run=false;keys.clear();heldPedals.clear();heldLift.clear();input.lift=input.elevator=input.aileron=input.rudder=0;stickPointer=null;stickX=stickY=0;wheelPointer=lookPointer=null;state.throttle=state.brake=0;}
 addEventListener('blur',()=>{release();actions.blur()});document.addEventListener('visibilitychange',()=>{if(document.hidden){release();actions.blur()}});
 return {input,release,center(){input.lookTarget=0;input.pitchTarget=0;},update(dt){input.lift=clamp([...heldLift.values()].reduce((a,b)=>a+b,0)+(keys.has('KeyZ')?1:0)-(keys.has('KeyX')?1:0),-1,1);if(state.onFoot){state.throttle=state.brake=0;input.moveX=clamp(walkX+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),-1,1);input.moveY=clamp(walkY+(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),-1,1);input.run=runHeld||keys.has('ShiftLeft')||keys.has('ShiftRight');}else if(state.flight){
 input.aileron=clamp(stickX+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),-1,1);input.elevator=clamp(stickY+input.lift+(keys.has('ArrowDown')?1:0)-(keys.has('ArrowUp')?1:0),-1,1);input.rudder=(keys.has('KeyE')?1:0)-(keys.has('KeyQ')?1:0);
 if(!heldPedals.has('throttle')){state.flightThrottle=clamp((state.flightThrottle??.72)+((keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0))*.4*dt,0,1);state.throttle=state.flightThrottle;}if(!heldPedals.has('brake'))state.brake=keys.has('Space')?1:0;
 }else{input.elevator=input.aileron=input.rudder=0;if(!heldPedals.has('throttle'))state.throttle=keys.has('KeyW')||keys.has('ArrowUp')?1:0;if(!heldPedals.has('brake'))state.brake=keys.has('KeyS')||keys.has('ArrowDown')?1:0;const left=keys.has('KeyA')||keys.has('ArrowLeft'),right=keys.has('KeyD')||keys.has('ArrowRight');if(wheelPointer===null){if(left||right)state.steering=clamp(state.steering+((right?1:0)-(left?1:0))*290*dt,-540,540);else state.steering*=Math.exp(-(1.4+Math.abs(state.speed)*.24)*dt);}}input.look+=(input.lookTarget-input.look)*(1-Math.exp(-10*dt));input.pitch+=(input.pitchTarget-input.pitch)*(1-Math.exp(-10*dt));},render(){if(walk)walk.querySelector('.walk-knob').style.transform=`translate(${input.moveX*90}%,${-input.moveY*90}%)`;run?.classList.toggle('selected',input.run);if(stick)stick.querySelector('.stick-knob').style.transform=`translate(${input.aileron*85}%,${input.elevator*85}%)`;art.style.transform=`rotate(${state.steering}deg)`;wheel.setAttribute('aria-valuenow',Math.round(state.steering));document.querySelector('#steer-degrees').textContent=Math.round(state.steering)+'°';for(const [id,key]of [['brake','brake'],['accelerator','throttle']]){const el=document.getElementById(id);const n=Math.round(state[key]*100);el.querySelector('.pedal-level').style.height=n+'%';el.querySelector('.pedal-percent').textContent=n+'%';el.setAttribute('aria-valuenow',n);}}};
}
